UPDATE public.translations SET
  english = 'The same performance depth from the FFF consultancy work is a central part of our complete representation model for our new stars.',
  spanish = 'La misma profundidad de rendimiento del trabajo de consultoría de FFF es una parte central de nuestro modelo completo de representación para nuestras nuevas estrellas.',
  portuguese = 'A mesma profundidade de desempenho do trabalho de consultoria da FFF é parte central do nosso modelo completo de representação para as nossas novas estrelas.',
  czech = 'Stejná hloubka výkonu z konzultační práce FFF je ústřední součástí našeho kompletního modelu zastupování pro naše nové hvězdy.',
  russian = 'Та же глубина работы над результативностью из консалтинга FFF является ключевой частью нашей полной модели представительства для наших новых звёзд.',
  french = 'La même profondeur de performance issue du travail de conseil de FFF est au cœur de notre modèle complet de représentation pour nos nouvelles stars.',
  german = 'Dieselbe Leistungstiefe aus der Beratungsarbeit von FFF ist ein zentraler Bestandteil unseres umfassenden Vertretungsmodells für unsere neuen Stars.',
  italian = 'La stessa profondità di performance del lavoro di consulenza FFF è parte centrale del nostro modello completo di rappresentanza per le nostre nuove stelle.',
  polish = 'Ta sama głębia pracy nad wynikami z konsultingu FFF stanowi centralny element naszego pełnego modelu reprezentacji dla naszych nowych gwiazd.',
  turkish = 'FFF danışmanlık çalışmalarındaki aynı performans derinliği, yeni yıldızlarımız için eksiksiz temsil modelimizin merkezinde yer alıyor.',
  croatian = 'Ista dubina rada na učinku iz FFF konzultantskog rada središnji je dio našeg cjelovitog modela zastupanja za naše nove zvijezde.',
  norwegian = 'Den samme prestasjonsdybden fra FFF-konsulentarbeidet er en sentral del av vår komplette representasjonsmodell for våre nye stjerner.',
  updated_at = now()
